    Long project,anchor,editorRoot,approverRoot,readerRoot;
    String scope="{\"entities\":[101],\"organizations\":[201],\"workerTypes\":[\"TEST\"],\"scenarios\":[\"TEST\"],\"from\":\"2026-10-01\",\"to\":\"2026-10-31\",\"explanation\":\"TEST synthetic scope\"}";
    String upper(){return scope.replace("[101]","[101,102]").replace("2026-10-31","2026-12-31");}
    @BeforeEach void setup(){
        ReflectionTestUtils.setField(decisions,"clock",Clock.system(ZONE));
        cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.setTenantId(1L);
        when(permissions.hasAnyPermissions(anyLong(),anyString())).thenReturn(true);
        for(long id=1;id<=4;id++)when(users.getUser(id)).thenReturn(new cn.iocoder.yudao.module.system.api.user.dto.AdminUserRespDTO().setId(id).setStatus(0).setNickname("TEST frozen user "+id));
        doReturn(Arrays.asList(map("id",1L,"nickname","TEST frozen user 1","status",0),map("id",2L,"nickname","TEST frozen user 2","status",0),map("id",3L,"nickname","TEST frozen user 3","status",0))).when(store).userFacts();
        store.insert(0L,"LOCK","TENANT",map());
        String body="TEST independently registered synthetic custodian and signer evidence; not formal business approval";
        anchor=store.insert(0L,"ANCHOR","TEST-INDEPENDENT-ANCHOR",map("state","REGISTERED","mode","TEST","custodianId",1L,"signerId",2L,"actions",new ArrayList<>(HrmPayrollRequirementAccessService.ACTIONS),"scopeJson",upper(),"validFrom","2026-01-01","validTo","2027-12-31","body",body,"digest",bodyDigest(body),"materialVersion","TEST-ANCHOR-V1")).getId();
        HrmPayrollRequirementProjectDO p=new HrmPayrollRequirementProjectDO().setProjectKey("TEST_S5").setName("TEST frozen project").setOwnerId(1L).setProjectScopeVersion(1).setMetadataVersion(1).setCustomSequence(0L).setScopeJson(scope).setArchived(false);projects.insert(p);project=p.getId();
        editorRoot=root(1L);approverRoot=root(2L);readerRoot=root(3L);
    }
    @AfterEach void clear(){cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.clear();}
    Root rootReq(Long user){Root c=new Root();c.setProjectId(project);c.setAnchorId(anchor);c.setUserId(user);c.setActions(new ArrayList<>(HrmPayrollRequirementAccessService.ACTIONS));c.setDelegableActions(new ArrayList<>(HrmPayrollRequirementAccessService.ACTIONS));c.setScopeJson(upper());c.setValidFrom("2026-01-01");c.setValidTo("2027-12-31");c.setMaterialVersion("TEST-ROOT-V1");c.setBody("TEST controlled root for user "+user);c.setReason("TEST independent signature fixture");return c;}
    Action action(Long id,String kind,String operation){Action a=new Action();a.setProjectId(project);a.setId(id);a.setVersion(store.record(id,kind).getVersion());a.setAction(operation);a.setReason("TEST independently authorized action");return a;}
    Long root(Long user){Long id=roots.register(rootReq(user),1L);roots.action(action(id,"ROOT","SIGN"),2L);return id;}
    HrmPayrollGovernanceVO.Decision draftReq(List<String> qs){HrmPayrollGovernanceVO.Decision c=new HrmPayrollGovernanceVO.Decision();c.setProjectId(project);c.setProjectScopeVersion(projects.selectById(project).getProjectScopeVersion());c.setTitle("TEST decision "+qs);c.setQuestions(qs);c.setClauses("TEST PRD v0.4 relevant clauses");c.setClauseVersion("TEST PRD v0.4 V1");c.setBody("TEST controlled decision "+qs);c.setScopeJson(projects.selectById(project).getScopeJson());c.setValidFrom("2026-01-01");c.setValidTo("2027-12-31");c.setApproverId(2L);c.setApprovalConditions("TEST independently checked material");c.setSemanticChange(false);Map<String,String> other=new LinkedHashMap<>();for(String q:Arrays.asList("Q-03","Q-06","Q-08","Q-09"))other.put(q,"ADVISORY");c.setOtherQuestions(other);c.setReason("TEST draft only");return c;}
    Long approve(HrmPayrollGovernanceVO.Decision c){Long id=decisions.draft(c,1L);decisions.action(action(id,"DECISION","SUBMIT"),1L);decisions.action(action(id,"DECISION","APPROVE"),2L);return id;}
    List<Long> policy(){return Arrays.asList(approve(draftReq(Arrays.asList("Q-01","Q-02","Q-07","Q-10"))),approve(draftReq(Collections.singletonList("Q-04"))),approve(draftReq(Collections.singletonList("Q-05"))));}
    Long requirement(){HrmPayrollRequirementSaveReqVO q=new HrmPayrollRequirementSaveReqVO();q.setProjectId(project);q.setProjectScopeVersion(projects.selectById(project).getProjectScopeVersion());q.setCode("CUSTOM-0000");q.setModule("COL");q.setDescription("TEST immutable requirement");q.setPriority(2);q.setStatus("PENDING");q.setReadiness("MISSING");q.setScopeMode("INHERIT");q.setRuleVersion("TEST RULE V1");q.setSourceApplicability("NOT_APPLICABLE");q.setApplicabilityReason("TEST discussion has no business data consumption");q.setAcceptance("TEST independent expected normal and exception result");q.setEvidence("TEST synthetic root and policy, not actual approval");q.setBusinessContextJson(JsonUtils.toJsonString(map("role","TEST HR","scenario","TEST monthly review","goal","TEST collect","expected","TEST expected result","normalCase","TEST normal","exceptionCase","TEST missing","calculation","TEST no monetary computation","unit","TEST not applicable discussion","precision","TEST not applicable discussion","validity","TEST 2026-10","ruleException","TEST return for review")));Long id=reqService.save(q,1L);reqService.assign(id,reqs.selectById(id).getVersion(),2L,1L);Decision d=new Decision();d.setProjectId(project);d.setProjectScopeVersion(q.getProjectScopeVersion());d.setId(id);d.setVersion(reqs.selectById(id).getVersion());d.setDecision("INCLUDED");d.setReason("TEST explicitly included");review.decide(d,1L);return id;}
    void confirm(Long id){reqService.confirm(id,reqs.selectById(id).getVersion(),2L);}
    Long source(Long req,String name){
        HrmPayrollWorkbenchVO.Source x=new HrmPayrollWorkbenchVO.Source();x.setName(name);x.setModule("COL");x.setScopeJson(scope);x.setOwnerId(1L);x.setTechnicalContact("TEST IT");x.setAcquisition("TEST file");x.setSpecification("TEST defined specification");x.setUniqueKey("employee,period");x.setEmployeeMatch("TEST employee identifier");x.setFrequency("monthly");x.setCutoff("month end");x.setVolume("TEST two rows");x.setQualityRule("TEST QS V1");HrmPayrollWorkbenchVO.Field field=new HrmPayrollWorkbenchVO.Field();field.setName("TEST_HIDDEN_FIELD");field.setMeaning("TEST recognized hours");field.setType("decimal");field.setUnit("hour");field.setRequired(true);x.setFields(Arrays.asList(field));
        HrmPayrollWorkbenchVO.SourceSave c=new HrmPayrollWorkbenchVO.SourceSave();c.setProjectId(project);c.setProjectScopeVersion(1);c.setReason("TEST source specification");c.setSource(x);Long source=workbench.saveSource(c,1L);
        HrmPayrollWorkbenchVO.Mapping m=new HrmPayrollWorkbenchVO.Mapping();m.setSourceField(field.getName());m.setPageField("workingHours");m.setMeaning(field.getMeaning());m.setType("decimal");m.setUnit("hour");m.setRequired(true);m.setTransform("TEST identity");m.setNullRule("reject");m.setDuplicateRule("reject");m.setPeriodRule("same month");m.setExceptionRule("TEST independent correction");
        HrmPayrollWorkbenchVO.Relation rel=new HrmPayrollWorkbenchVO.Relation();rel.setSourceId(source);rel.setRequirementId(req);rel.setConsumptionRule("TEST QC V1");rel.setFields(Arrays.asList(m));HrmPayrollWorkbenchVO.RelationSave rc=new HrmPayrollWorkbenchVO.RelationSave();rc.setProjectId(project);rc.setProjectScopeVersion(1);rc.setReason("TEST defined mapping");rc.setRelation(rel);Long relation=workbench.saveRelation(rc,1L);
        verify(source,"SOURCE","SOURCE_SEMANTIC");verify(relation,"RELATION","RELATION_SEMANTIC");return source;
    }
    void verify(Long id,String kind,String layer){Map<?,?>d=(Map<?,?>)workbench.detail(project,kind,id,2L);HrmPayrollWorkbenchVO.Verify c=new HrmPayrollWorkbenchVO.Verify();c.setProjectId(project);c.setProjectScopeVersion(1);c.setId(id);c.setVersion(workbenchRecords.selectById(id).getVersion());c.setReason("TEST independent specification review");c.setLayer(layer);c.setExpectedBinding(String.valueOf(((Map<?,?>)d.get("bindings")).get(layer)));c.setReference("TEST independently executed semantic check");c.setSampleDigest("TEST specification, no delivered dataset");c.setResult("PASS");workbench.verify(c,2L);}
    Long applicable(){Long r=requirement();HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(reqs.selectById(r)),HrmPayrollRequirementSaveReqVO.class);q.setSourceApplicability("APPLICABLE");q.setApplicabilityReason("");reqService.save(q,1L);return r;}
    Publish request(boolean draft){Map<String,Object> gate=releases.precheck(project,1L);Publish p=new Publish();p.setProjectId(project);p.setProjectScopeVersion(projects.selectById(project).getProjectScopeVersion());p.setRequestKey(UUID.randomUUID().toString());p.setDependencyToken(String.valueOf(gate.get("dependencyToken")));p.setDraft(draft);p.setReason("TEST synthetic release, not formal");return p;}
    @Test void technicalPermissionAndOldRootCannotManufactureControlledAuthority(){Long pending=roots.register(rootReq(4L),1L);assertThrows(RuntimeException.class,()->roots.action(action(pending,"ROOT","SIGN"),1L));assertThrows(RuntimeException.class,()->roots.authority(project,4L,"BASELINE_PUBLISH",scope));HrmPayrollRequirementProjectDO p=projects.selectById(project);p.setProjectKey("FORMAL_PROJECT");projects.updateById(p);assertThrows(RuntimeException.class,()->roots.register(rootReq(4L),1L));}
    @Test void missingPolicyRejectsConfirmationWithoutAddingSignature(){Long r=requirement();assertThrows(RuntimeException.class,()->confirm(r));assertNull(reqs.selectById(r).getConfirmedBy());assertFalse(Boolean.TRUE.equals(releases.precheck(project,1L).get("allowed")));}
    @Test void approvalIsIndependentAndOldBodyIsImmutable(){List<Long> ds=policy();Long old=ds.get(1);String original=store.data(store.record(old,"DECISION")).get("body").toString();HrmPayrollGovernanceVO.Decision c=draftReq(Collections.singletonList("Q-04"));c.setPreviousId(old);c.setBody("TEST new matrix body");Long next=decisions.draft(c,1L);decisions.action(action(next,"DECISION","SUBMIT"),1L);assertThrows(RuntimeException.class,()->decisions.action(action(next,"DECISION","APPROVE"),1L));assertEquals("EFFECTIVE",decisions.lifecycle(store.data(store.record(old,"DECISION"))));decisions.action(action(next,"DECISION","APPROVE"),2L);assertEquals("REPLACED",decisions.lifecycle(store.data(store.record(old,"DECISION"))));assertEquals(original,store.data(store.record(old,"DECISION")).get("body"));}
    @Test void overlappingIndependentDecisionFamiliesAreRejected(){policy();Long duplicate=decisions.draft(draftReq(Collections.singletonList("Q-04")),1L);decisions.action(action(duplicate,"DECISION","SUBMIT"),1L);assertThrows(RuntimeException.class,()->decisions.action(action(duplicate,"DECISION","APPROVE"),2L));assertEquals("PENDING_APPROVAL",store.data(store.record(duplicate,"DECISION")).get("state"));}
    @Test void matrixReplacementPreservesSignatureButRuleReplacementRequiresRereview(){List<Long> ds=policy();Long r=requirement();confirm(r);Integer v=reqs.selectById(r).getVersion();HrmPayrollGovernanceVO.Decision matrix=draftReq(Collections.singletonList("Q-04"));matrix.setPreviousId(ds.get(1));matrix.setBody("TEST updated matrix, same business semantics");approve(matrix);assertEquals(v,reqs.selectById(r).getVersion());assertEquals("CONFIRMED",reqs.selectById(r).getStatus());HrmPayrollGovernanceVO.Decision rule=draftReq(Collections.singletonList("Q-05"));rule.setPreviousId(ds.get(2));rule.setBody("TEST changed acceptance semantics");approve(rule);assertEquals("REVIEWING",reqs.selectById(r).getStatus());assertNull(reqs.selectById(r).getConfirmedBy());confirm(r);assertEquals("CONFIRMED",reqs.selectById(r).getStatus());}
    @Test void futureAndExpiredVersionsAreCalculatedWithoutChangingSystemTime(){policy();HrmPayrollGovernanceVO.Decision c=draftReq(Collections.singletonList("Q-04"));Long old=id(((Map<?,?>)decisions.current(project,scope,Collections.singletonList("Q-04")).get(0)).get("recordId"));c.setPreviousId(old);c.setValidFrom("2026-10-20T09:00:00");c.setBody("TEST future matrix");ReflectionTestUtils.setField(decisions,"clock",Clock.fixed(Instant.parse("2026-10-19T08:00:00Z"),ZONE));Long next=approve(c);assertEquals("FUTURE",decisions.lifecycle(store.data(store.record(next,"DECISION"))));assertEquals("EFFECTIVE",decisions.lifecycle(store.data(store.record(old,"DECISION"))));ReflectionTestUtils.setField(decisions,"clock",Clock.fixed(Instant.parse("2026-10-20T02:00:00Z"),ZONE));assertEquals("EFFECTIVE",decisions.lifecycle(store.data(store.record(next,"DECISION"))));assertEquals("REPLACED",decisions.lifecycle(store.data(store.record(old,"DECISION"))));ReflectionTestUtils.setField(decisions,"clock",Clock.fixed(Instant.parse("2028-01-01T02:00:00Z"),ZONE));assertEquals("EXPIRED",decisions.lifecycle(store.data(store.record(next,"DECISION"))));}
    @Test void publishAndRetriesRequireCurrentRootAndExactDependencyAndRequest(){policy();Long r=requirement();confirm(r);Publish c=request(false);assertTrue((Boolean)releases.precheck(project,1L).get("allowed"));Long id=releases.publish(c,1L);assertEquals(id,releases.publish(c,1L));c.setReason("TEST changed content under same key");assertThrows(RuntimeException.class,()->releases.publish(c,1L));c.setReason("TEST synthetic release, not formal");roots.action(action(editorRoot,"ROOT","REVOKE"),2L);assertThrows(RuntimeException.class,()->releases.publish(c,1L));}
    @Test void unrelatedProjectRootAnchorAndPersonnelCannotInvalidatePublishOrExactRetry(){
        policy();Long requirement=requirement();confirm(requirement);Publish command=request(false);
        HrmPayrollRequirementProjectDO other=JsonUtils.parseObject(JsonUtils.toJsonString(projects.selectById(project)),HrmPayrollRequirementProjectDO.class);
        other.setId(null);other.setProjectKey("TEST_UNRELATED");projects.insert(other);
        Root root=rootReq(4L);root.setProjectId(other.getId());Long otherRoot=roots.register(root,1L);
        String body="TEST unrelated independently registered anchor";
        store.insert(0L,"ANCHOR","TEST-UNRELATED",map("state","REGISTERED","mode","TEST","body",body,"digest",bodyDigest(body)));
        doReturn(Arrays.asList(map("id",1L,"nickname","TEST frozen user 1","status",0),map("id",2L,"nickname","TEST frozen user 2","status",0),map("id",3L,"nickname","TEST frozen user 3","status",0),map("id",4L,"nickname","TEST unrelated renamed user","status",0))).when(store).userFacts();
        assertEquals(command.getDependencyToken(),releases.precheck(project,1L).get("dependencyToken"));
        Long release=releases.publish(command,1L);
        Action sign=action(otherRoot,"ROOT","SIGN");sign.setProjectId(other.getId());roots.action(sign,2L);
        assertEquals(release,releases.publish(command,1L));
        assertEquals(1,store.all(project,"RELEASE").size());
    }
    @Test void relatedAnchorAndPersonnelChangesStillInvalidatePreparedPublication(){
        policy();Long requirement=requirement();confirm(requirement);Publish command=request(false);
        doReturn(Arrays.asList(map("id",1L,"nickname","TEST changed relevant user","status",0),map("id",2L,"nickname","TEST frozen user 2","status",0),map("id",3L,"nickname","TEST frozen user 3","status",0))).when(store).userFacts();
        final Publish beforePersonnelChange=command;
        assertThrows(RuntimeException.class,()->releases.publish(beforePersonnelChange,1L));
        final Publish prepared=request(false);
        HrmPayrollGovernanceRecordDO current=store.record(anchor,"ANCHOR");Map<String,Object> data=store.data(current);data.put("materialVersion","TEST-ANCHOR-V2");store.state(current,data);
        assertThrows(RuntimeException.class,()->releases.publish(prepared,1L));
        assertTrue(store.all(project,"RELEASE").isEmpty());
    }
