    @Test void emptyProjectOnlyCreatesFixedEmptyDraft(){policy();assertFalse((Boolean)releases.precheck(project,1L).get("allowed"));assertThrows(RuntimeException.class,()->releases.publish(request(false),1L));Long release=releases.publish(request(true),1L);Map<String,Object> p=projection.project(project,release,1L,"READ",null);assertEquals("空草稿",p.get("label"));}
    @Test void archiveAndStaleScopeAndUnexplainedExclusionBlockPublication(){policy();Long r=requirement();confirm(r);Publish c=request(false);HrmPayrollRequirementProjectDO p=projects.selectById(project);p.setArchived(true);projects.updateById(p);assertFalse((Boolean)releases.precheck(project,1L).get("allowed"));assertThrows(RuntimeException.class,()->releases.publish(c,1L));p.setArchived(false);projects.updateById(p);projectService.scope(project,1,upper(),"TEST explicitly expanded scope",1L);assertThrows(RuntimeException.class,()->releases.publish(c,1L));assertThrows(RuntimeException.class,()->confirm(r));}
    @Test void fixedSnapshotKeepsOldNamesRulesDeclarationsAndStatisticsAfterCurrentChanges(){List<Long> ds=policy();Long r=requirement();confirm(r);Long release=releases.publish(request(false),1L);Map<String,Object> before=projection.project(project,release,1L,"EXPORT",null);HrmPayrollRequirementDO row=reqs.selectById(r);row.setDescription("TEST changed current text");reqs.updateById(row);when(users.getUser(2L)).thenReturn(new cn.iocoder.yudao.module.system.api.user.dto.AdminUserRespDTO().setId(2L).setStatus(0).setNickname("TEST NEW NAME"));HrmPayrollGovernanceVO.Decision matrix=draftReq(Collections.singletonList("Q-04"));matrix.setPreviousId(ds.get(1));matrix.setBody("TEST NEW MATRIX");approve(matrix);Map<String,Object> after=projection.project(project,release,1L,"EXPORT",null);assertEquals(JsonUtils.toJsonString(before),JsonUtils.toJsonString(after));assertTrue(JsonUtils.toJsonString(after).contains("TEST frozen user 2"));assertFalse(JsonUtils.toJsonString(after).contains("TEST NEW NAME"));}
    @Test void downloadRechecksAuthorizationAtEveryStageAndOldJobsCannotBeClaimed() throws Exception {policy();Long r=requirement();confirm(r);Long release=releases.publish(request(false),1L);Job c=new Job();c.setProjectId(project);c.setReleaseId(release);Long job=exports.create(c,3L);exports.generate(project,job,3L);assertEquals("READY",exports.status(project,job,3L).get("state"));assertTrue(exports.claim(project,job,3L).length>0);roots.action(action(readerRoot,"ROOT","REVOKE"),2L);assertThrows(RuntimeException.class,()->exports.status(project,job,3L));assertThrows(RuntimeException.class,()->exports.claim(project,job,3L));assertThrows(RuntimeException.class,()->projection.project(project,release,3L,"READ",null));}
    @Test void sixSheetsKeepLongChineseTextAndNaStatementWithoutAFakeSourceId() throws Exception {policy();Long r=requirement();confirm(r);Long release=releases.publish(request(false),1L);Map<String,Object> p=projection.project(project,release,1L,"EXPORT",null);String text="中文长正文🌿";StringBuilder longText=new StringBuilder();for(int n=0;n<7000;n++)longText.append(text);Map<String,List<Map<String,Object>>> tables=(Map<String,List<Map<String,Object>>>)p.get("sheets");tables.get("评审版本说明").add(map("记录类型","DECISION","记录号","LONG","正文",longText.toString()));byte[] bytes=HrmPayrollGovernanceExportService.workbook(p,1L);try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){assertEquals(6,book.getNumberOfSheets());for(int n=0;n<6;n++)assertEquals(HrmPayrollGovernanceProjectionService.SHEETS.get(n),book.getSheetName(n));org.apache.poi.ss.usermodel.Sheet s=book.getSheetAt(0);StringBuilder reconstructed=new StringBuilder();org.apache.poi.ss.usermodel.Row row=s.getRow(s.getLastRowNum()-1);for(int col=0;col<s.getRow(0).getLastCellNum();col++)if(s.getRow(0).getCell(col).getStringCellValue().startsWith("正文"))reconstructed.append(row.getCell(col).getStringCellValue());assertEquals(longText.toString(),reconstructed.toString());}String sources=JsonUtils.toJsonString(tables.get("数据源清单"));assertTrue(sources.contains("不适用声明"));assertFalse(sources.contains("sourceId"));}
    @Test void definedSpecificationsCanPublishWhileDataSupplyIsStillMissing(){policy();Long r=applicable();source(r,"TEST_PRIVATE_SOURCE_ONE");confirm(r);assertTrue((Boolean)releases.precheck(project,1L).get("allowed"));Long release=releases.publish(request(false),1L);Map<String,Object> p=projection.project(project,release,1L,"EXPORT",null);Map<?,?> stats=(Map<?,?>)p.get("statistics");assertEquals("0/1",((Map<?,?>)stats.get("readiness")).get("label"));assertEquals("1/1",((Map<?,?>)stats.get("confirmation")).get("label"));Map<String,List<Map<String,Object>>> sheets=(Map<String,List<Map<String,Object>>>)p.get("sheets");assertEquals(1,sheets.get("功能需求清单").size());assertEquals(1,sheets.get("范围与变更").size());}
    @Test void hiddenSourcesAndPublicationEvidenceAreMergedWithoutIdsNamesFieldsOrCounts(){policy();Long r=applicable();source(r,"TEST_PRIVATE_SOURCE_ONE");source(r,"TEST_PRIVATE_SOURCE_TWO");confirm(r);Long release=releases.publish(request(false),1L);roots.action(action(readerRoot,"ROOT","REVOKE"),2L);HrmPayrollRequirementProjectGrantDO g=new HrmPayrollRequirementProjectGrantDO();g.setProjectId(project);g.setUserId(3L);g.setActions("READ,EXPORT");g.setDelegableActions("");g.setFullProject(false);g.setRequirementIdsJson("["+r+"]");g.setModulesJson("[\"COL\"]");g.setCeilingJson(scope);g.setValidFrom(LocalDate.of(2026,1,1));g.setValidTo(LocalDate.of(2027,12,31));g.setEvidence("TEST independently delegated narrow export");projectService.grant(g,1L);Map<String,Object> p=projection.project(project,release,3L,"EXPORT",null);String text=JsonUtils.toJsonString(p);assertTrue(text.contains("权限受限节选"));assertFalse(text.contains("TEST_PRIVATE_SOURCE_ONE"));assertFalse(text.contains("TEST_PRIVATE_SOURCE_TWO"));assertFalse(text.contains("TEST_HIDDEN_FIELD"));Map<?,?> stats=(Map<?,?>)p.get("statistics");assertEquals("0/1",((Map<?,?>)stats.get("readiness")).get("label"));assertEquals(0,stats.get("sourceCount"));Map<String,List<Map<String,Object>>> sheets=(Map<String,List<Map<String,Object>>>)p.get("sheets");assertEquals(1,sheets.get("数据源清单").size());assertEquals(1,sheets.get("字段映射").size());assertEquals(1,sheets.get("评审版本说明").stream().filter(x->"GRANT".equals(x.get("记录类型"))).count());}
