    @Test void queuedGenerationAndNewJobsRejectAfterCurrentRootRevocation() throws Exception {policy();Long r=requirement();confirm(r);Long release=releases.publish(request(false),1L);Job c=new Job();c.setProjectId(project);c.setReleaseId(release);Long job=exports.create(c,3L);roots.action(action(readerRoot,"ROOT","REVOKE"),2L);assertThrows(RuntimeException.class,()->exports.generate(project,job,3L));assertThrows(RuntimeException.class,()->exports.create(c,3L));assertThrows(RuntimeException.class,()->exports.status(project,job,3L));assertThrows(RuntimeException.class,()->exports.claim(project,job,3L));assertEquals("QUEUED",store.data(store.record(job,"JOB")).get("state"));}
    @Test void sourceAuthorityCannotStitchAnotherModulesControlledGrant() {policy();Long r=applicable();Long src=source(r,"TEST SOURCE");roots.action(action(readerRoot,"ROOT","REVOKE"),2L);HrmPayrollRequirementProjectGrantDO g=new HrmPayrollRequirementProjectGrantDO();g.setProjectId(project);g.setUserId(3L);g.setActions("READ,SOURCE_VERIFY");g.setDelegableActions("");g.setFullProject(false);g.setModulesJson("[\"TAX\"]");g.setSourceIdsJson("["+src+"]");g.setCeilingJson(scope);g.setValidFrom(LocalDate.of(2026,1,1));g.setValidTo(LocalDate.of(2027,12,31));g.setEvidence("TEST unrelated module grant");projectService.grant(g,1L);assertThrows(RuntimeException.class,()->roots.authority(project,3L,"SOURCE_VERIFY",scope,null,src));}
    @Test void replacedDecisionReferencedByOldConfirmationStillHasResolvableSnapshotRow(){List<Long> ds=policy();Long r=requirement();confirm(r);HrmPayrollGovernanceVO.Decision matrix=draftReq(Collections.singletonList("Q-04"));matrix.setPreviousId(ds.get(1));matrix.setBody("TEST current matrix, old confirmation remains historical fact");Long next=approve(matrix);Long release=releases.publish(request(false),1L);Map<String,Object> p=projection.project(project,release,1L,"EXPORT",null);Map<String,List<Map<String,Object>>> sheets=(Map<String,List<Map<String,Object>>>)p.get("sheets");List<Map<String,Object>> summary=sheets.get("评审版本说明");assertTrue(summary.stream().anyMatch(x->("DEC-"+ds.get(1)).equals(x.get("记录号"))));assertTrue(summary.stream().anyMatch(x->("DEC-"+next).equals(x.get("记录号"))));assertEquals(summary.size(),summary.stream().map(x->x.get("记录号")).distinct().count());}
    @Test void inactiveMappingAndRemovedNaDeclarationRemainResolvableInFrozenSixTables(){policy();Long r=applicable();Long sid=source(r,"TEST historical source");confirm(r);Long v1=releases.publish(request(false),1L);HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(reqs.selectById(r)),HrmPayrollRequirementSaveReqVO.class);q.setSourceApplicability("NOT_APPLICABLE");q.setApplicabilityReason("TEST metadata discussion no longer consumes source fields");q.setStatus("REVIEWING");reqService.save(q,1L);confirm(r);Long removed=requirement();Decision d=new Decision();d.setProjectId(project);d.setProjectScopeVersion(1);d.setId(removed);d.setVersion(reqs.selectById(removed).getVersion());d.setDecision("REMOVED");d.setRemovalKind("MISTAKE");d.setReason("TEST explicitly removed mistaken metadata request");review.decide(d,1L);Long v2=releases.publish(request(false),1L);Map<String,Object> p=projection.project(project,v2,1L,"EXPORT",null);Map<String,List<Map<String,Object>>> sheets=(Map<String,List<Map<String,Object>>>)p.get("sheets");assertEquals(2,sheets.get("范围与变更").size());assertEquals(2,sheets.get("数据源清单").stream().filter(x->"不适用声明".equals(x.get("记录类型"))).count());assertTrue(sheets.get("字段映射").stream().anyMatch(x->"MAPPING".equals(x.get("记录类型"))&&Boolean.FALSE.equals(x.get("关系当前生效"))));assertEquals(0,((Map<?,?>)p.get("statistics")).get("sourceCount"));assertTrue(JsonUtils.toJsonString(projection.project(project,v1,1L,"EXPORT",null)).contains("TEST historical source"));}
    @Test void visibleSourceAndMappingDoNotExposeRestrictedDecisionFreeText(){policy();Long r=applicable();Long sid=source(r,"TEST visible source");HrmPayrollWorkbenchRecordDO src=workbenchRecords.selectById(sid);Map<String,Object> sd=JsonUtils.parseObject(src.getDataJson(),Map.class);sd.put("specification","TEST_RESTRICTED_POLICY_BODY");src.setDataJson(JsonUtils.toJsonString(sd));workbenchRecords.updateById(src);HrmPayrollWorkbenchRecordDO rel=workbenchRecords.selectList().stream().filter(x->"RELATION".equals(x.getKind())).findFirst().get();Map<String,Object> rd=JsonUtils.parseObject(rel.getDataJson(),Map.class);((Map<String,Object>)((List<?>)rd.get("fields")).get(0)).put("transform","TEST_RESTRICTED_POLICY_BODY");rel.setDataJson(JsonUtils.toJsonString(rd));workbenchRecords.updateById(rel);verify(sid,"SOURCE","SOURCE_SEMANTIC");verify(rel.getId(),"RELATION","RELATION_SEMANTIC");confirm(r);Long release=releases.publish(request(false),1L);roots.action(action(readerRoot,"ROOT","REVOKE"),2L);HrmPayrollRequirementProjectGrantDO g=new HrmPayrollRequirementProjectGrantDO();g.setProjectId(project);g.setUserId(3L);g.setActions("READ,EXPORT,PERSON_READ");g.setDelegableActions("");g.setFullProject(true);g.setCeilingJson(scope);g.setValidFrom(LocalDate.of(2026,1,1));g.setValidTo(LocalDate.of(2027,12,31));g.setEvidence("TEST explicit source read/export, no decision or authority read");projectService.grant(g,1L);String projected=JsonUtils.toJsonString(projection.project(project,release,3L,"EXPORT",null));assertTrue(projected.contains("TEST visible source"));assertFalse(projected.contains("TEST_RESTRICTED_POLICY_BODY"));assertTrue(projected.contains("受限发布依据"));}
    @Test void listingManyRowsResolvesCurrentAuthorityOnceAndRechecksNextRead(){
        for(int n=0;n<50;n++)requirement();
        clearInvocations(users);
        List<HrmPayrollRequirementDO> first=projectService.rows(project,null,3L,"READ");
        assertEquals(50,first.size());
        assertTrue(first.stream().allMatch(r->r.getPermittedActions().contains("READ")));
        // Regression guard for the 60s list timeout: authority work must not multiply
        // by both the number of rows and the full action matrix.
        assertTrue(mockingDetails(users).getInvocations().size()<100);
        roots.action(action(readerRoot,"ROOT","REVOKE"),2L);
        assertThrows(RuntimeException.class,()->projectService.rows(project,null,3L,"READ"));
        assertEquals(50,projectService.rows(project,null,1L,"READ").size());
    }
    @Test void readLocalSourceGraphIsDiscardedAfterFailureAndCannotCrossProjects(){
        policy();Long r=applicable();Long src=source(r,"TEST graph before");
        assertThrows(IllegalStateException.class,()->workbench.withReadSnapshot(project,()->{throw new IllegalStateException("TEST read failure");}));
        HrmPayrollWorkbenchRecordDO record=workbenchRecords.selectById(src);
        Map<String,Object> d=JsonUtils.parseObject(record.getDataJson(),Map.class);
        d.put("name","TEST graph after");record.setDataJson(JsonUtils.toJsonString(d));workbenchRecords.updateById(record);
        Map<?,?> current=(Map<?,?>)workbench.withReadSnapshot(project,()->workbench.detail(project,"SOURCE",src,1L));
        assertTrue(JsonUtils.toJsonString(current).contains("TEST graph after"));
        assertThrows(RuntimeException.class,()->workbench.withReadSnapshot(project+999,()->workbench.detail(project+999,"SOURCE",src,1L)));
    }

